	runtime.SetGlobal(ctx, "lookup2DkernelInfo", runtime.NewNativeFunction(ctx.Global, []runtime.NativeParameter{{Name: "kernel"}}, func(ctx *runtime.Context, env *runtime.Environment) (runtime.Value, error) {
		_ = runtime.MustCallIn(ctx, env, "validate2Dkernel", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "kernel")))
		runtime.SetLocal(env, "kernel", runtime.MustCallIn(ctx, env, "match2DkernelName", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "kernel"))))
		if runtime.MustTrue(runtime.MustCallIn(ctx, env, "is.null", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "kernel")))) {
			return runtime.NullValue, nil
		}
		return runtime.MustCallIn(ctx, env, "[[", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, ".Spatstat.2D.KernelTable")), runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "kernel"))), nil
	}))

	// r2go: matrix lowering unavailable for block 5/6; original R follows.
	// R| evaluate2Dkernel <- function(kernel, x, y, sigma=NULL, varcov=NULL, ...,
