	// R|                    alternative=alternative,
	// R|                    leaveout=leaveout,
	// R|                    interpolate=interpolate,
	// R|                    confint=FALSE, verbose=FALSE, ...)
	// R|   phati <- sapply(T2list, getElement, name="pest")
	// R|   ## Dao-Genton p-value
	// R|   if(verbose) cat(" Computing significance trace...")
	// R|   result <- mctestSigtraceEngine(R, -phat, -phati,
	// R|                                  interpolate=FALSE,
	// R|                                  confint=confint,
	// R|                                  exponent=exponent,
	// R|                                  alpha=alpha,
	// R|                                  unitname=unitname(X))
	// R|   if(verbose) cat(" Done.\n")
