const rtdal007570Source0001 = `edit.ppp <- local({

  edit.ppp <- function(name, ...) {
    X <- name
    df <- as.data.frame(X)
    df <- as.data.frame(lapply(df, as.num.or.char))
    Y <- edit(df, ...)
    Z <- as.ppp(Y, W=Window(X))
    return(Z)
  }

  as.num.or.char <- function(x) {
    if (is.character(x)) x else
    if (is.numeric(x)) {
      storage.mode(x) <- "double"
      x
    } else as.character(x)
  }

  edit.ppp
})`

