const rtdal007580Source0002 = `fourierbasisraw <- function(x, k, boxlengths) {
  two_pi_i <- 2 * pi * (0+1i)
  rslt <- outer(k[, 1L], x[, 1L]/boxlengths[1L])
  d <- ncol(x)
  if (d > 1) {
    for (i in 2:d) {
      rslt <- rslt + outer(k[, i], x[, i]/boxlengths[i])
    }
  }
  return(exp(two_pi_i * rslt)/sqrt(prod(boxlengths)))
}`

