const rtdal007581Source0008 = `plot.funxy <- function(x, ...) {
  xname <- short.deparse(substitute(x))
  force(x)
  W <- as.owin(x)
  result <- do.call(do.as.im,
                    resolve.defaults(list(quote(x), action="plot"),
                                     list(...),
                                     list(main=xname, W=W)))
  return(invisible(result))
}`

