const rtdal007581Source0010 = `persp.funxy <- function(x, ...) {
  xname <- short.deparse(substitute(x))
  zlab <- substitute(expression(f(x,y)), list(f=as.name(xname)))
  force(x)
  W <- as.rectangle(as.owin(x))
  result <- do.call(do.as.im,
                    resolve.defaults(list(quote(x), action="persp"),
                                     list(...),
                                     list(main=xname, W=W, zlab=zlab)))
  return(invisible(result))
}`

const rtdal007581Source0011 = `hist.funxy <- function(x, ..., xname) {
  if(missing(xname) || is.null(xname)) xname <- short.deparse(substitute(x))
  a <- do.call.matched(as.im,
                       list(X=x, ...),
                       c("X", "W",
		         "dimyx", "eps", "xy",
                         "rule.eps",
   		         "na.replace", "strict"),
		       sieve=TRUE)
  Z <- a$result
  do.call(hist.im, append(list(x=Z, xname=xname), a$otherargs))
}`

