const rtdal007595Source0001 = `levelset <- function(X, thresh, compare="<=", ...) {
  UseMethod("levelset")
}`

const rtdal007595Source0002 = `levelset.im <- function(X, thresh, compare="<=", ...) {
  # force X and thresh to be evaluated in this frame
  verifyclass(X, "im")
  thresh <- thresh
  A <- switch(compare,
         "<"  = eval.im(X < thresh),
         ">"  = eval.im(X > thresh),
         "<=" = eval.im(X <= thresh),
         ">=" = eval.im(X >= thresh),
         "==" = eval.im(X == thresh),
         "!=" = eval.im(X != thresh),
         stop(paste("unrecognised comparison operator", sQuote(compare))))
  W <- as.owin(eval.im(ifelse1NA(A)))
  return(W)
}`

const rtdal007595Source0003 = `levelset.default <- function(X, thresh, compare="<=", ...) {
  # last resort: convert X to image
  X <- as.im(X, ...)
  W <- levelset.im(X, thresh, compare)
  return(W)
}`

const rtdal007595Source0004 = `solutionset <- function(..., envir) {
  if(missing(envir))
    envir <- parent.frame()
  A <- try(eval.im(..., envir=envir), silent=TRUE)
  if(inherits(A, "try-error"))
    A <- try(eval(..., envir=envir), silent=TRUE)
  if(inherits(A, "try-error"))
    stop("Unable to evaluate expression")
  if(!is.im(A))
    stop("Evaluating the expression did not yield a pixel image")
  if(A$type != "logical")
    stop("Evaluating the expression did not yield a logical-valued image")
  W <- as.owin(eval.im(ifelse1NA(A)))
  return(W)
}`

