const rtdal007604Source0001 = `erosion  <- function(w, r, ...) { UseMethod("erosion") }`

const rtdal007604Source0002 = `dilation <- function(w, r, ...) { UseMethod("dilation") }`

const rtdal007604Source0003 = `closing  <- function(w, r, ...) { UseMethod("closing") }`

const rtdal007604Source0004 = `opening  <- function(w, r, ...) { UseMethod("opening") }`

const rtdal007604Source0005 = `erosion.owin <- 
  function(w, r, shrink.frame=TRUE, ..., strict=FALSE, polygonal=NULL) {
  verifyclass(w, "owin")
  validradius(r, "erosion")
  if(r == 0 && !strict)
    return(w)
  u <- unitname(w)
  
  xr <- w$xrange
  yr <- w$yrange

  #' If erosion would obliterate the frame itself,
  #' return empty window in original frame
  if(2 * r >= max(diff(xr), diff(yr)))
    return(emptywindow(Frame(w)))

  #' Compute the (nonempty) eroded frame
  exr <- xr + c(r, -r)
  eyr <- yr + c(r, -r)
  efpoly <- list(x=exr[c(1,2,2,1)], y=eyr[c(1,1,2,2)])
  eframe <- owin(exr, eyr, unitname=u)

  #' Erosion of an empty window is empty
  if(is.empty(w)) {
    OutFrame <- if(shrink.frame) eframe else Frame(w)
    return(emptywindow(OutFrame))
  }
  
  #' Determine type of computation
  ismask <- is.mask(w)
  if(is.null(polygonal))
    polygonal <- !ismask
  else {
    stopifnot(is.logical(polygonal))
    if(polygonal && ismask) {
      #' try to convert
      w <- as.polygonal(w)
      if(is.mask(w))
        polygonal <- FALSE
    }
  }
  
  if(is.rectangle(w) && polygonal) {
    #' Result is a smaller rectangle exr * eyr
    if(shrink.frame) {
      #' type 'rectangle'
      return(eframe)  
    } else {
      #' type 'polygonal' representing rectangle
      return(owin(xr, yr, poly=efpoly, unitname=u, check=FALSE)) 
    }
  }

  if(polygonal) {
    #' compute eroded polygonal region using polyclip package
    pnew <- polyclip::polyoffset(w$bdry, -r, jointype="round")
    #' ensure correct polarity of polygon data
    if(length(pnew) > 0) {
      totarea <- sum(unlist(lapply(pnew, Area.xypolygon)))
      if(totarea < 0)
        pnew <- lapply(pnew, reverse.xypolygon)
    }
    if(shrink.frame) {
      return(owin(exr, eyr, poly=pnew, unitname=u, check=FALSE))
    } else {
      return(owin( xr,  yr, poly=pnew, unitname=u, check=FALSE))
    }
  }
  
  #' Otherwise erode the window in pixel image form
  if(w$type == "mask") {
    wnew <- erodemask(w, r, strict=strict)
  } else {
    D <- distmap(w, invert=TRUE, ...)
    wnew <- levelset(D, r, if(strict) ">" else ">=")
  }
        
  if(shrink.frame) {
    #' trim off some rows & columns of pixel raster
    keepcol <- (wnew$xcol >= exr[1] & wnew$xcol <= exr[2])
    keeprow <- (wnew$yrow >= eyr[1] & wnew$yrow <= eyr[2])
    wnew$xcol <- wnew$xcol[keepcol]
    wnew$yrow <- wnew$yrow[keeprow]
    wnew$dim <- c(sum(keeprow), sum(keepcol))
    wnew$m <- wnew$m[keeprow, keepcol]
    wnew$xrange <- exr
    wnew$yrange <- eyr
  }

  return(wnew)
}`

const rtdal007604Source0006 = `dilation.owin <- 
  function(w, r, ..., polygonal=NULL, tight=TRUE) {
  verifyclass(w, "owin")
  validradius(r, "dilation")
  
  if(r == 0)
    return(w)

  if(is.empty(w))
    return(w)

  u <- unitname(w)
  
  # determine type of computation
  if(is.null(polygonal)) {
    polygonal <- !is.mask(w)
  } else stopifnot(is.logical(polygonal))
  
  if(polygonal) {
    # convert to polygonal 
    w <- as.polygonal(w)
    if(!is.polygonal(w))
      polygonal <- FALSE
  }
  
  #' bounding frame for result
  bb <- if(tight) boundingbox(w) else as.rectangle(w)
  newbox <- grow.rectangle(bb, r)

  # compute dilation
  if(!polygonal) {
    #' compute pixel approximation of dilation using distance transform
    if(length(list(...))) 
      w <- as.mask(w=w, ...)
    if(is.mask(w)) {
      #' for computation, expand frame to an integer multiple of pixel size
      xstep <- w$xstep
      ystep <- w$ystep
      delta <- 2 * .Machine$double.eps
      rx <- xstep * ceiling(delta + r/xstep)
      ry <- ystep * ceiling(delta + r/ystep)
      safebox <- grow.rectangle(bb, rx, ry)
      w <- rebound.owin(w, safebox)
    }
    #' distance transform
    distant <- distmap(w)
    #' threshold (allowing for numerical effects)
    epsilon <- with(distant, sqrt(xstep^2 + ystep^2)/16)
    dil <- levelset(distant, r + epsilon, "<=")
    #' clip
    dil <- dil[newbox]
    return(dil)
  } else {
    #' compute polygonal region using polyclip package
    pnew <- polyclip::polyoffset(w$bdry, r, jointype="round")
    #' ensure correct polarity of polygon data
    if(length(pnew) > 0) {
      totarea <- sum(unlist(lapply(pnew, Area.xypolygon)))
      if(totarea < 0)
        pnew <- lapply(pnew, reverse.xypolygon)
    }
    # determine bounding frame, convert to owin
    if(tight && length(pnew) > 0) {
      out <- owin(poly=pnew,
                  unitname=u, check=FALSE)
    } else {
      out <- owin(newbox$xrange, newbox$yrange,
                  poly=pnew,
                  unitname=u, check=FALSE)
    }
    return(out)
  }
}`

const rtdal007604Source0007 = `closing.owin <- function(w, r, ..., polygonal=NULL) {
  if(missing(r))
    stop("r is required")
  validradius(r, "closing")
  wplus <- dilation.owin(w, r, ..., polygonal=polygonal, tight=FALSE)
  if(is.empty(wplus))
    return(wplus)
  wclose <- erosion.owin(wplus, r, strict=TRUE)
  b <- as.rectangle(w)
  wclose <- rebound.owin(wclose[b], b)
  return(wclose)
}`

const rtdal007604Source0008 = `opening.owin <- function(w, r, ..., polygonal=NULL) {
  if(missing(r))
    stop("r is required")
  validradius(r, "opening")
  wminus <- erosion.owin(w, r, ..., polygonal=polygonal, shrink.frame=FALSE)
  if(is.empty(wminus))
    return(wminus)
  wopen <- dilation.owin(wminus, r, tight=FALSE)
  b <- as.rectangle(w)
  wopen <- rebound.owin(wopen[b], b)
  return(wopen)
}`

const rtdal007604Source0009 = `border <- function(w, r, outside=FALSE, ...) {
  w <- as.owin(w)
  if(!outside) {
    e <- erosion(w, r, ...)
    b <- setminus.owin(w, e)
  } else {
    d <- dilation(w, r, ...)
    b <- setminus.owin(d, w)
  }
  return(b)
}`

const rtdal007604Source0010 = `dilation.psp <- function(w, r, ..., polygonal=TRUE, tight=TRUE) {
  verifyclass(w, "psp")
  x <- w
  validradius(r, "dilation")
  if(r == 0)
    return(w)

  if(is.empty(x))
    return(emptywindow(as.owin(w)))
  
  # bounding frame
  bb <- if(tight) boundingbox(x) else as.rectangle(x)
  newbox <- grow.rectangle(bb, r)
  
  # compute dilation
  if(!polygonal) {
    x <- rebound.psp(x, newbox)
    distant <- distmap(x, ...)
    dil <- levelset(distant, r, "<=")
    return(dil)
  } else if(spatstat.options("old.morpho.psp")) {
    # old code for polygonal case
    ends   <- x$ends
    angles <- angles.psp(x, directed=TRUE)
#    lengths <- lengths_psp(x)
    out <- NULL
    # dilate individual segments
    halfcircle <- seq(from=0, to=pi, length.out=128)[-c(1,128)]
    for(i in seq_len(x$n)) {
      seg <- ends[i,]
      co <- cos(angles[i])
      si <- sin(angles[i])
      # draw sausage around i-th segment
      xx <- c(seg$x0, seg$x1) + r * si
      yy <- c(seg$y0, seg$y1) - r * co
      rightcircle <- angles[i] - pi/2 + halfcircle
      xx <- c(xx, seg$x1 + r * cos(rightcircle))
      yy <- c(yy, seg$y1 + r * sin(rightcircle))
      xx <- c(xx, c(seg$x1, seg$x0) - r * si)
      yy <- c(yy, c(seg$y1, seg$y0) + r * co)
      leftcircle <- angles[i] + pi/2 + halfcircle
      xx <- c(xx, seg$x0 + r * cos(leftcircle))
      yy <- c(yy, seg$y0 + r * sin(leftcircle))
      sausage <- owin(newbox$xrange, newbox$yrange, poly=list(x=xx, y=yy), check=FALSE)
      # add to set
      out <- union.owin(out, sausage, ...)
    }
    return(out)
  } else {
    # new code using 'polyclip' package
    # convert to list of list(x,y)
    ends   <- as.matrix(x$ends)
    n <- nrow(ends)
    plines <- vector(mode="list", length=n)
    for(i in 1:n) plines[[i]] <- list(x=ends[i, c("x0","x1")],
                                      y=ends[i, c("y0","y1")])
    # call
    pnew <- polyclip::polylineoffset(plines, r,
                                     jointype="round", endtype="openround")
    # ensure correct polarity
    totarea <- sum(unlist(lapply(pnew, Area.xypolygon)))
    if(totarea < 0)
      pnew <- lapply(pnew, reverse.xypolygon)
    # convert to owin object
    out <- if(tight) owin(poly=pnew, check=FALSE) else
            owin(newbox$xrange, newbox$yrange, poly=pnew, check=FALSE)
    return(out)
  }
}`

const rtdal007604Source0011 = `closing.psp <- function(w, r, ..., polygonal=TRUE) {
  if(missing(r))
    stop("r is required")
  validradius(r, "closing")
  wplus <- dilation.psp(w, r, ..., polygonal=polygonal, tight=FALSE)
  if(is.empty(wplus))
    return(emptywindow(as.owin(w)))
  wclose <- erosion.owin(wplus, r, strict=TRUE)
  wclose <- rebound.owin(wclose, as.rectangle(w))
  return(wclose)
}`

const rtdal007604Source0012 = `erosion.psp <- function(w, r, ...) {
  idorempty(w, r, "erosion")
}`

