const rtdal007635Source0013 = `coords.ppx <- function(x, ..., spatial=TRUE, temporal=TRUE, local=TRUE) {
  ctype <- x$ctype
  chosen <- (ctype == "spatial" & spatial) |
            (ctype == "temporal" & temporal) | 
            (ctype == "local" & local) 
  as.data.frame(x$data[, chosen, drop=FALSE])
}`

const rtdal007635Source0014 = `coords.ppp <- function(x, ...) { data.frame(x=x$x,y=x$y) }`

const rtdal007635Source0015 = `"coords<-" <- function(x, ..., value) {
  UseMethod("coords<-")
}`

const rtdal007635Source0016 = `"coords<-.ppp" <- function(x, ..., value) {
  win <- x$window
  if(is.null(value)) {
    # empty pattern
    return(ppp(window=win))
  }
  value <- as.data.frame(value)
  if(ncol(value) != 2)
    stop("Expecting a 2-column matrix or data frame, or two vectors")
  result <- as.ppp(value, win, ...)
  marks(result) <- marks(x)
  return(result)
}`

const rtdal007635Source0017 = `"coords<-.ppx" <- function(x, ..., spatial=TRUE, temporal=TRUE, local=TRUE, value) {
  ctype <- x$ctype
  chosen <- (ctype == "spatial" & spatial) |
            (ctype == "temporal" & temporal) | 
            (ctype == "local" & local) 
  x$data[, chosen] <- value
  return(x)
}`

const rtdal007635Source0018 = `as.hyperframe.ppx <- function(x, ...) { x$data }`

