const rtdal007644Source0003 = `rsyst <- function(win=square(1), nx=NULL, ny=nx, ..., dx=NULL, dy=dx,
                  nsim=1, drop=TRUE) {
  if(!missing(nsim)) {
    check.1.integer(nsim)
    stopifnot(nsim >= 0)
  }
  win <- as.owin(win)
  xr <- win$xrange
  yr <- win$yrange
  ## determine grid coordinates 
  if(missing(ny)) ny <- NULL
  if(missing(dy)) dy <- NULL
  g <- xy.grid(xr, yr, nx, ny, dx, dy)
  x0 <- g$x0
  y0 <- g$y0
  dx <- g$dx
  dy <- g$dy
  ## assemble grid and randomise location
  xy0 <- expand.grid(x=x0, y=y0)
  result <- vector(mode="list", length=nsim)
  for(isim in seq_len(nsim)) {
    x <- xy0$x + runif(1, min = 0, max = dx)
    y <- xy0$y + runif(1, min = 0, max = dy)
    Xbox <- ppp(x, y, xr, yr, check=FALSE)
    ## trim to window
    result[[isim]] <- Xbox[win]
  }
  result <- simulationresult(result, nsim, drop)
  return(result)
}`

const rtdal007644Source0005 = `rjitter <- function(X, ...) {
  UseMethod("rjitter")
}`

const rtdal007644Source0006 = `rjitter.ppp <- function(X, radius, retry=TRUE, giveup=10000, trim=FALSE, ...,
                        nsim=1, drop=TRUE, adjust=1) {
  verifyclass(X, "ppp")
  if(!missing(nsim)) {
    check.1.integer(nsim)
    stopifnot(nsim >= 0)
  }
  nX <- npoints(X)
  W <- Window(X)
  if(nX == 0) {
    result <- rep(list(X), nsim)
    result <- simulationresult(result, nsim, drop)
    return(result)
  }
  #' determine the jitter radius
  if(missing(radius) || is.null(radius)) {
    ## default: Stoyan rule of thumb
    bws <- 0.15/sqrt(5 * nX/area(W))
    radius <- min(bws, shortside(Frame(W)))
  } else {
    ## either one radius, or a vector of radii
    check.nvector(radius, nX, oneok=TRUE, vname="radius")
    check.finite(radius, xname="radius")
    if(min(radius) < 0) {
      warning("Negative values of jitter radius were set to zero")
      radius <- pmax(0, radius)
    }
  }
  #' trim?
  if(isTRUE(trim)) 
    radius <- pmin(radius, bdist.points(X))
  #' adjust the jitter radius
  if(!missing(adjust)) {
    check.nvector(adjust, nX, oneok=TRUE, vname="adjust")
    if(min(adjust) < 0) {
      nbad <- sum(adjust < 0)
      howmanyvalues <- if(length(adjust) == 1) {
                         "the value"
                       } else {
                         paste(nbad, ngettext(nbad, "value", "values"))
                       }
      warning(paste("Negative sign was ignored in",
                    howmanyvalues, "of", sQuote("adjust")),
              call.=FALSE)
      adjust <- abs(adjust)
    }
    radius <- adjust * radius
  }
  #'
  sameradius <- (length(radius) == 1)
  #' start jitterin'
  result <- vector(mode="list", length=nsim)
  for(isim in seq_len(nsim)) {
    Xshift <- X
    if(!retry) {
      ## points outside window are lost
      rD <- radius * sqrt(runif(nX))
      aD <- runif(nX, max= 2 * pi)
      Xshift$x <- xx <- X$x + rD * cos(aD)
      Xshift$y <- yy <- X$y + rD * sin(aD)
      ok <- inside.owin(xx, yy, W)
      Xshift <- Xshift[ok]
    } else {
      ## retry = TRUE: condition on points being inside window
      undone <- rep.int(TRUE, nX)
      triesleft <- giveup
      while(any(undone)) {
        triesleft <- triesleft - 1
        if(triesleft <= 0) 
	  break
        Y <- Xshift[undone]
        nY <- npoints(Y)
        RY <- if(sameradius) radius else radius[undone]
        rD <- RY * sqrt(runif(nY))
        aD <- runif(nY, max= 2 * pi)
        xnew <- Y$x + rD * cos(aD)
        ynew <- Y$y + rD * sin(aD)
        ok <- inside.owin(xnew, ynew, W)
        if(any(ok)) {
          changed <- which(undone)[ok]
          Xshift$x[changed] <- xnew[ok]
          Xshift$y[changed] <- ynew[ok]
          undone[changed] <- FALSE
        }
      }
      attr(Xshift, "tries") <- giveup - triesleft
    }
    attr(Xshift, "radius") <- radius
    result[[isim]] <- Xshift
  }
  result <- simulationresult(result, nsim, drop)
  return(result)
}`

const rtdal007644Source0007 = `rjitter.pp3 <- function(X, radius, retry=TRUE, giveup=10000, trim=FALSE, ...,
                        nsim=1, drop=TRUE, adjust=1) {
  verifyclass(X, "pp3")
  if(!missing(nsim)) {
    check.1.integer(nsim)
    stopifnot(nsim >= 0)
  }
  if(is.NAobject(X) || (nX <- npoints(X)) == 0) {
    result <- rep(list(X), nsim)
    result <- simulationresult(result, nsim, drop)
    return(result)
  }
  B <- domain(X)
  #' determine the jitter radius
  if(missing(radius) || is.null(radius)) {
    radius <- shortside(B)/5
  } else {
    ## either one radius, or a vector of radii
    check.nvector(radius, nX, oneok=TRUE, vname="radius")
    check.finite(radius, xname="radius")
    if(min(radius) < 0) {
      warning("Negative values of jitter radius were set to zero")
      radius <- pmax(0, radius)
    }
  }
  #' trim?
  if(isTRUE(trim)) 
    radius <- pmin(radius, distbdry(X))
  #' adjust the jitter radius
  if(!missing(adjust)) {
    check.nvector(adjust, nX, oneok=TRUE, vname="adjust")
    if(min(adjust) < 0) {
      nbad <- sum(adjust < 0)
      howmanyvalues <- if(length(adjust) == 1) {
                         "the value"
                       } else {
                         paste(nbad, ngettext(nbad, "value", "values"))
                       }
      warning(paste("Negative sign was ignored in",
                    howmanyvalues, "of", sQuote("adjust")),
              call.=FALSE)
      adjust <- abs(adjust)
    }
    radius <- adjust * radius
  }
  #'
  sameradius <- (length(radius) == 1)
  #' start jitterin'
  result <- vector(mode="list", length=nsim)
  for(isim in seq_len(nsim)) {
    Xshift <- X
    if(!retry) {
      ## retry = FALSE: points outside window are lost
      xyzshift <- coords(Xshift) + radius * runifSphereCoords(nX)
      ok <- with(xyzshift, inside.box3(x, y, z, B))
      Xshift <- Xshift[ok]
      if(any(ok)) 
        coords(Xshift) <- xyzshift[ok,,drop=FALSE]
    } else {
      ## retry = TRUE: condition on points being inside window
      undone <- rep.int(TRUE, nX)
      triesleft <- giveup
      while(any(undone)) {
        triesleft <- triesleft - 1
        if(triesleft <= 0) 
	  break
        Y <- Xshift[undone]
        nY <- npoints(Y)
        RY <- if(sameradius) radius else radius[undone]
        xyzshift <- coords(Y) + radius * runifSphereCoords(nY)
        ok <- with(xyzshift, inside.box3(x, y, z, B))
        if(any(ok)) {
          changed <- which(undone)[ok]
          coords(Xshift)[changed, ] <- xyzshift[ok, ]
          undone[changed] <- FALSE
        }
      }
      attr(Xshift, "tries") <- giveup - triesleft
    }
    attr(Xshift, "radius") <- radius
    result[[isim]] <- Xshift
  }
  result <- simulationresult(result, nsim, drop)
  return(result)
}`

