const rtdal007656Source0001 = `split.ppp <- function(x, f = marks(x), drop=FALSE, un=NULL, reduce=FALSE, ...) {
  verifyclass(x, "ppp")
  mf <- markformat(x)
  fgiven <- !missing(f)
  
  if(is.null(un)) {
    un <- !fgiven && (mf != "dataframe")
  } else un <- as.logical(un)

  if(!fgiven) {
    # f defaults to marks of x
    switch(mf,
           none={
             stop("f is missing and there are no marks")
           },
           vector={
             if(!is.multitype(x)) 
               stop("f is missing and the pattern is not multitype")
             f <- fsplit <- marks(x)
           },
           dataframe={
             f <- fsplit <- firstfactor(marks(x))
             if(is.null(f))
               stop("Data frame of marks contains no factors")
           })
    splittype <- "factor"
  } else {
    # f was given
    fsplit <- f
    if(is.factor(f)) {
      splittype <- "factor"
    } else if(is.logical(f)) {
      splittype <- "factor"
      f <- factor(f)
    } else if(is.tess(f)) {
      # f is a tessellation: determine the grouping
      f <- marks(cut(x, fsplit))
      splittype <- "tess"
    } else if(is.owin(f)) {
      # f is a window: coerce to a tessellation
      W <- as.owin(x)
      fsplit <- tess(tiles=list(fsplit, setminus.owin(W, fsplit)),
                     window=W)
      f <- marks(cut(x, fsplit))
      splittype <- "tess"
    } else if(is.im(f)) {
      # f is an image: coerce to a tessellation
      fsplit <- tess(image=f)
      f <- marks(cut(x, fsplit))
      splittype <- "tess"
    } else if(is.character(f) && length(f) == 1) {
      # f should be 'marks' or the name of a column of marks
      marx <- marks(x)
      switch(markformat(x),
             none = {
               stop(paste("The name", sQuote(f),
                          "does not specify a column of marks",
                          "(there are no marks)"),
                    call.=FALSE)
             },
             vector = {
               if(f != "marks") 
                 stop(paste("The name", sQuote(f),
                            "does not specify a column of marks",
                            "(the marks are a vector)"),
                      call.=FALSE)
               fsplit <- f <- as.factor(marx)
             },
             dataframe = ,
             hyperframe = {
               if(!(f %in% colnames(marx))) 
                 stop(paste("The name", sQuote(f),
                            "does not match any column of marks"),
                      call.=FALSE)
               fsplit <- f <- as.factor(marx[,f, drop=TRUE])
             },
             stop(paste("The name", sQuote(f), "is not recognised as a column of marks"),
                  call.=FALSE)
             )
      splittype <- "factor"
    } else 
      stop(paste("f must be",
                 "a factor, a logical vector,", 
                 "a tessellation, a window, an image,",
                 "or the name of a column of marks"))
    if(length(f) != npoints(x))
      stop("length(f) must equal the number of points in x")
  }

  # At this point
  # 'f' is a factor that can be used to separate the points
  # 'fsplit' is the object (either a factor or a tessellation)
  # that determines the split (and can be "un-split")

  lev <- levels(f)
  if(drop) {
    # remove components that don't contain points
    retain <- (table(f) > 0)
    lev <- lev[retain]
    switch(splittype,
           tess = {
             # remove tiles that don't contain points
             fsplit <- fsplit[retain]
           },
           factor = {
             # delete levels that don't occur
             fsplit <- factor(fsplit, levels=lev)
           },
           stop("Internal error: wrong format for fsplit"))
  }

  ## remove marks that will not be retained
  if(un && reduce && mf == "dataframe")
    warning("Incompatible arguments un=TRUE and reduce=TRUE: assumed un=TRUE")
  if(un) {
    x <- unmark(x)
  } else if(reduce && !fgiven && mf == "dataframe") {
    # remove the column of marks that determined the split
    j <- findfirstfactor(marks(x))
    if(!is.null(j))
      marks(x) <- marks(x)[, -j]
  }
  
  ## split the data
  out <- list()
  fok <- !is.na(f)
  for(l in lev) 
    out[[paste(l)]] <- x[fok & (f == l)]

  ## 
  if(splittype == "tess") {
    til <- tiles(fsplit)
    for(i in seq_along(out))
      out[[i]]$window <- til[[i]]
  }
  class(out) <- unique(c("splitppp", "ppplist", "solist", class(out)))
  attr(out, "fsplit") <- fsplit
  attr(out, "fgroup") <- f
  return(out)
}`

const rtdal007656Source0002 = "\"split<-.ppp\" <- function(x, f=marks(x), drop=FALSE, un=NULL,\n                          ..., value) {\n  verifyclass(x, \"ppp\")\n  W <- x$window\n  fgiven <- !missing(f)\n  mf <- markformat(x)\n  \n  # evaluate `un' before assigning value of 'f'\n  if(is.null(un)) {\n    un <- !fgiven && (mf != \"dataframe\")\n  } else un <- as.logical(un)\n\n  # validate assignment value\n  stopifnot(is.list(value))\n  if(!all(unlist(lapply(value, is.ppp))))\n    stop(paste(\"Each entry of\", sQuote(\"value\"),\n               \"must be a point pattern\"))\n\n  ismark <- unlist(lapply(value, is.marked))\n  if(any(ismark) && !all(ismark))\n    stop(paste(\"Some entries of\",\n               sQuote(\"value\"),\n               \"are marked, and others are unmarked\"))\n  vmarked <- all(ismark)\n\n  # determine type of splitting\n  if(missing(f)) {\n    # f defaults to marks of x\n    switch(mf,\n           none={\n             stop(\"f is missing and there are no marks\")\n           },\n           vector={\n             if(!is.multitype(x)) \n               stop(\"f is missing and the pattern is not multitype\")\n             f <- fsplit <- marks(x)\n           },\n           dataframe={\n             f <- fsplit <- firstfactor(marks(x))\n             if(is.null(f))\n               stop(\"Data frame of marks contains no factors\")\n           })\n  } else {\n    # f given\n    fsplit <- f\n    if(is.tess(f)) {\n      # f is a tessellation: determine the grouping\n      f <- marks(cut(x, fsplit))\n    } else if(is.im(f)) {\n      # f is an image: determine the grouping\n      fsplit <- tess(image=f)\n      f <- marks(cut(x, fsplit))\n    } else if(is.character(f) && length(f) == 1) {\n      # f is the name of a column of marks\n      marx <- marks(x)\n      if(is.data.frame(marx) && (f %in% names(marx))) \n        fsplit <- f <- marx[[f]]\n      else\n        stop(paste(\"The name\", sQuote(f), \"does not match any column of marks\"))\n    } else if(is.logical(f)) {\n      f <- factor(f)\n    } else if(!is.factor(f))\n      stop(paste(\"f must be\",\n                 \"a factor, a logical vector, a tessellation, an image,\",\n                 \"or the name of a column of marks\"))\n    if(length(f) != x$n)\n      stop(\"length(f) must equal the number of points in x\")\n  } \n  #\n  all.levels <- lev <- levels(f)\n  if(!drop) \n    levtype <- \"levels of f\"\n  else {\n    levtype <- \"levels which f actually takes\"\n    # remove components that don't contain points\n    lev <- lev[table(f) > 0]\n  }\n  if(length(value) != length(lev))\n      stop(paste(\"length of\", sQuote(\"value\"),\n                 \"should equal the number of\",\n                 levtype))\n\n  # ensure value[[i]] is associated with lev[i]\n  if(!is.null(names(value))) {\n    if(!all(names(value) %in% as.character(lev)))\n      stop(paste(\"names of\", sQuote(\"value\"), \"should be levels of f\"))\n    value <- value[lev]\n  }\n  names(value) <- NULL\n\n  # restore the marks, if they were discarded\n  if(un && is.marked(x)) {\n    if(vmarked)\n      warning(paste(sQuote(\"value\"), \"contains marked point patterns:\",\n                    \"this is inconsistent with un=TRUE; marks ignored.\"))\n    for(i in seq_along(value)) \n      value[[i]] <- value[[i]] %mark% factor(lev[i], levels=all.levels)\n  }\n\n  # handle NA's in splitting factor\n  if(any(isNA <- is.na(f))) {\n    xNA <- x[isNA]\n    if(un && is.marked(x)) \n      xNA <- xNA %mark% factor(NA, levels=all.levels)\n    value <- append(value, list(xNA))\n  }\n\n  # put Humpty together again\n  if(npoints(x) == length(f) &&\n     length(levels(f)) == length(value) &&\n     all(table(f) == sapply(value, npoints))) {\n    ## exact correspondence\n    out <- x\n    for(i in seq_along(levels(f)))\n      out[ f == lev[i] ] <- value[[i]]\n  } else {\n    out <- do.call(superimpose,c(value,list(W=W)))\n  }\n  return(out)\n}"

const rtdal007656Source0003 = `print.splitppp <- function(x, ...) {
  f <- attr(x, "fsplit")
  what <- if(is.tess(f)) "tessellation" else
          if(is.factor(f)) "factor" else 
          if(is.logical(f)) "logical vector" else typeof(f)
  cat(paste("Point pattern split by", what, "\n"))
  nam <- names(x)
  for(i in seq_along(x)) {
    cat(paste("\n", nam[i], ":\n", sep=""))
    print(x[[i]])
  }
  return(invisible(NULL))
}`

const rtdal007656Source0004 = `summary.splitppp <- function(object, ...) {
  x <- lapply(object, summary, ...)
  class(x) <- "summary.splitppp"
  x
}`

const rtdal007656Source0005 = `print.summary.splitppp <- function(x, ...) {
  class(x) <- "anylist"
  print(x)
  invisible(NULL)
}`

const rtdal007656Source0006 = `"[.splitppp" <- function(x, ...) {
  f <- attr(x, "fsplit")
  # invoke list method on x
  class(x) <- "list"
  y <- x[...]
  # then make it a 'splitppp' object too
  class(y) <- c("splitppp", class(y))
  if(is.tess(f)) {
    fsplit <- f[...]
  } else if(is.factor(f)) {
    lev <- levels(f)
    sublev <- lev[...]
    subf <- f[f %in% sublev]
    fsplit <- factor(subf, levels=lev)
  } else stop("Unknown splitting type")
  attr(y, "fsplit") <- fsplit
  y
}`

const rtdal007656Source0007 = `"[<-.splitppp" <- function(x, ..., value) {
  if(!all(unlist(lapply(value, is.ppp))))
    stop("replacement value must be a list of point patterns")
  f <- attr(x, "fsplit")
  # invoke list method
  class(x) <- "list"
  x[...] <- value
  # then make it a 'splitppp' object too
  class(x) <- c("splitppp", class(x))
  if(is.tess(f)) {
    fsplit <- f
  } else if(is.factor(f)) {
    lev <- levels(f)
    fsplit <- factor(rep.int(lev, unlist(lapply(x, npoints))), levels=lev)
  }
  attr(x, "fsplit") <- fsplit
  x
}`

const rtdal007656Source0008 = `plot.splitppp <- local({

  plot.splitppp <- function(x, ..., main) {
    if(missing(main)) main <- short.deparse(substitute(x))
    plsplp(x, ..., main=main)
  }

  plsplp <- function(x, ..., main, plotcommand="plot", equal.scales) {
    if(missing(equal.scales))
      equal.scales <- plotcommand %in% c("plot", "image")
    plot.solist(x, ..., main=main,
                plotcommand=plotcommand, equal.scales=equal.scales)
  }
  
  plot.splitppp
})`

