const rtdal007673Source0006 = `"unitname<-" <- function(x, value) {
  UseMethod("unitname<-")
}`

const rtdal007673Source0007 = `"unitname<-.owin" <- function(x, value) {
  x$units <- as.unitname(value)
  return(x)
}`

const rtdal007673Source0008 = `"unitname<-.ppp" <- function(x, value) {
  w <- x$window
  unitname(w) <- value
  x$window <- w
  return(x)
}`

const rtdal007673Source0009 = `"unitname<-.im" <- function(x, value) {
  x$units <- as.unitname(value)
  return(x)
}`

const rtdal007673Source0010 = `"unitname<-.default" <- function(x, value) {
  if(is.null(x)) return(x)
  attr(x, "units") <- as.unitname(value)
  return(x)
}`

const rtdal007673Source0011 = `makeunitname <- function(sing="unit", plur="units", mul = 1) {
  if(!is.character(sing))
    stop("In unit name, first entry should be a character string")
  if(!is.character(plur))
    stop("In unit name, second entry should be a character string")
  mul <- try(as.numeric(mul), silent=TRUE)
  if(inherits(mul, "try-error"))
    stop("In unit name, third entry should be a number")
  if(length(mul) != 1 || mul <= 0)
    stop("In unit name, third entry should be a single positive number")
  u <- list(singular=sing, plural=plur, multiplier=mul)
  if(mul != 1 && (sing=="unit" || plur=="units"))
    stop(paste("A multiplier is not allowed",
               "if the unit does not have a specific name"))
  class(u) <- "unitname"
  return(u)
}`

const rtdal007673Source0013 = `print.unitname <- function(x, ...) {
  mul <- x$multiplier
  if(mul == 1)
    cat(paste(x$singular, "/", x$plural, "\n"))
  else 
    cat(paste(mul, x$plural, "\n"))
  return(invisible(NULL))
}`

const rtdal007673Source0014 = `as.character.unitname <- function(x, ...) {
  mul <- x$multiplier
  return(if(mul == 1) x$plural else paste(mul, x$plural))
}`

const rtdal007673Source0016 = `summary.unitname <- function(object, ...) {
  x <- object
  scaled <- (x$multiplier != 1)
  named  <- (x$singular != "unit")
  vanilla <- !named && !scaled
  out <-
    if(vanilla) {
      list(legend = NULL,
           axis   = NULL, 
           explain = NULL,
           singular = "unit",
           plural   = "units")
    } else if(named & !scaled) {
      list(legend = paste("Unit of length: 1", x$singular),
           axis   = paren(x$plural, type=spatstat.options('units.paren')),
           explain = NULL,
           singular = x$singular,
           plural   = x$plural)
    } else {
      expanded <- paste(x$multiplier, x$plural)
      expla <- paren(paste("one unit =", expanded),
                     type=spatstat.options('units.paren'))
      list(legend = paste("Unit of length:", expanded),
           axis   = expla, 
           explain  = expla,
           singular = "unit",
           plural   = "units")
    }
  out <- append(out, list(scaled  = scaled,
                          named   = named,
                          vanilla = vanilla))
  class(out) <- "summary.unitname"
  return(out)
}`

const rtdal007673Source0017 = `print.summary.unitname <- function(x, ...) {
  if(x$vanilla)
    cat("Unit of length (unnamed)\n")
  else
    cat(paste(x$legend, "\n"))
  invisible(NULL)
}`

const rtdal007673Source0018 = `compatible <- function(A, B, ...) {
  UseMethod("compatible")
}`

const rtdal007673Source0019 = "compatible.unitname <- function(A, B, ..., coerce=TRUE) {\n  A <- as.unitname(A)\n  if(missing(B)) return(TRUE)\n  B <- as.unitname(B)\n  # check for null units\n  Anull <- summary(A)$vanilla\n  Bnull <- summary(B)$vanilla\n  # `coerce' determines whether `vanilla' units are compatible with other units\n  coerce <- as.logical(coerce)\n  # \n  agree <- if(!Anull && !Bnull) isTRUE(all.equal(A,B)) else\n           if(Anull && Bnull) TRUE else coerce \n  #\n  if(!agree) return(FALSE)\n  # A and B agree\n  if(length(list(...)) == 0) return(TRUE)\n  # recursion\n  return(compatible.unitname(B, ...))\n}"

const rtdal007673Source0020 = `harmonize.unitname <-
harmonise.unitname <- function(..., coerce=TRUE, single=FALSE) {
  argh <- list(...)
  if(length(argh) == 1) {
    ## single argument, could be a list of unitnames
    a <- argh[[1L]]
    if(all(sapply(a, is.null) | sapply(a, inherits, what="unitname")))
      argh <- a
  }
  n <- length(argh)
  if(n == 0) return(NULL)
  u <- lapply(argh, as.unitname)
  if(n == 1) return(if(single) u[[1L]] else u)
  if(coerce) {
    #' vanilla units are compatible with another unit
    s <- lapply(u, summary)
    v <- sapply(s, getElement, name="vanilla")
    if(all(v))
      return(if(single) u[[1L]] else u)
    u <- u[!v]
  }
  z <- unique(u)
  if(length(z) > 1) stop("Unitnames are incompatible", call.=FALSE)
  if(single) return(z[[1]])
  z <- rep(z, n)
  names(z) <- names(argh)
  return(z)
}`

const rtdal007673Source0021 = `numberwithunit <- function(x, u, modifier=NULL) {
  u <- as.unitname(u)
  x <- as.numeric(x)
  unitname(x) <- u
  class(x) <- c(class(x), "numberwithunit")
  attr(x, "modifier") <- modifier
  return(x)
}`

const rtdal007673Source0022 = `"%unit%" <- function(x, u) {
  numberwithunit(x, u)
}`

const rtdal007673Source0023 = `format.numberwithunit <- function(x, ..., collapse=" x ", modifier=NULL) {
  if(missing(modifier)) modifier <- attr(x, "modifier")
  u <- summary(unitname(x))
  uname <- if(all(x == 1)) u$singular else u$plural
  y <- format(as.numeric(x), ...)
  z <- pasteN(paste(y, collapse=collapse), 
              modifier, uname, u$explain)
  return(z)
}`

const rtdal007673Source0024 = `as.character.numberwithunit <- function(x, ...) {
  return(format(x))
}`

const rtdal007673Source0025 = `print.numberwithunit <- function(x, ...) {
  cat(format(x, ...), fill=TRUE)
  return(invisible(NULL))
}`

